INSERT INTO `pendaftaran_magang` VALUES (3,'260714000003','Kevin Atharegan Shafareno','kevinatha07@gmail.com','085747512169',NULL,'Universitas Negeri Semarang','S1 Ekonomi Pembangunan ','Belum Ditentukan',6,'Wajib','2026-01-19','2026-06-12','1767844638_1c855d982dd2d7e5de6a.pdf','1767844638_b0f962c44f72bcced6d4.pdf','1767844638_c7ad8b4b9bbd0110006c.pdf',NULL,'Lolos_Final',NULL,NULL,NULL,NULL,'',0,'2026-07-21 14:10:53',0,1,NULL,NULL,NULL,'Lolos Final',NULL,NULL,'2026-01-15 14:00:00',NULL,NULL,NULL,NULL,NULL,'2026-01-08 10:57:18','2026-07-21 17:21:58'),(7,'260714000007','Agatha Namira Syahrani','agatha250206@gmail.com','085335574840',NULL,'Universitas Katolik Soegijapranata Semarang','Psikologi','Belum Ditentukan',4,'Mandiri','2026-01-26','2026-03-13','1768975222_7dd7701d3717c3daea8d.pdf','1768975222_61ce3799ec33cdcdca77.pdf','1768975222_45a309b7a3b38e003796.pdf',NULL,'Lolos_Final',NULL,NULL,NULL,NULL,'',0,'2026-07-21 14:10:53',0,1,NULL,NULL,NULL,'Halo Agatha Namira!\n\nSelamat Pagi,\nPerkenalkan saya Reisya Aurelya Yusfandira dari Capability Building Indosat Ooredo Hutchison Semarang. Sebelumnya, terima kasih atas ketertarikanmu mendaftar pada program Internship IOH.\n\nSelamat!! kamu dinyatakan lolos tahap interview 1 dan akan melanjutkan interview tahap 2.\n\nDitunggu informasi lebih lanjut untum tahap selanjutnya yaa!\n\n❗Catatan Penting❗\n•⁠  ⁠Bawa CV Hardfile \n\nJika kamu berkenan, jangan lupa mengonfirmasi Kehadiran dengan membalas pesan ini, dengan format: \nNamaLengkap_Hadir\n\nTerima kasih, selamat mempersiapkan diri dan kami tunggu Kehadiranmu!\n\nSalam hangat,\nReisya Aurelya Yusfandira\nCapability Building Intern','[PENGUMUMAN INTERNSHIP IOH]\n\nHalo, Agatha Namira!\n\nTerima kasih atas partisipasi saudari dalam proses seleksi program Internship IOH.\n\nBerdasarkan hasil evaluasi tahap interview, dengan ini  kami sampaikan bahwa saudari dinyatakan LOLOS dan diterima untuk bergabung sebagai Internship Divisi Capability Building\n\nKami percaya bahwa kemampuan dan semangatmu akan menjadi kontribusi yang positif bagi tim kami.\n\nSebelum melakukan internship, kami akan mengundang kamu untuk melakukan handover yang dimulai pada :\nHari/Tanggal : Jumat, 30 Januari 2026\nJam : 10:00 WIB\nLokasi : Indosat Ooredoo Hutchison Pandanaran Semarang\n\nTerima kasih, dan selamat mempersiapkan diri!\n\nSalam hangat,\nReisya Aurelya Yusfandira\nCapability Building Intern','[PENGUMUMAN INTERNSHIP IOH]  Halo, Agatha Namira!  Terima kasih atas partisipasi saudari dalam proses seleksi program Internship IOH.  Berdasarkan hasil evaluasi tahap interview, dengan ini  kami sampaikan bahwa saudari dinyatakan *LOLOS* dan diterima untuk bergabung sebagai Internship Divisi Capability Building  Kami percaya bahwa kemampuan dan semangatmu akan menjadi kontribusi yang positif bagi tim kami.  Sebelum melakukan internship, kami akan mengundang kamu untuk melakukan handover yang dimulai pada : Hari/Tanggal : Jumat, 30 Januari 2026 Jam : 10:00 WIB Lokasi : Indosat Ooredoo Hutchison Pandanaran Semarang  Terima kasih, dan selamat mempersiapkan diri!  Salam hangat, Reisya Aurelya Yusfandira Capability Building Intern','2026-01-23 14:00:00',NULL,NULL,NULL,NULL,NULL,'2026-01-21 13:00:22','2026-07-21 17:21:58'),(8,'260714000008','Devani Permata Saputra','devanipermata56@students.unnes.ac.id','089530476447',NULL,'Universitas Negeri Semarang','Ekonomi Pembangunan','Belum Ditentukan',6,'Wajib','2026-02-09','2026-05-29','1769666690_f14db699fbc17c261a3a.pdf','1769666690_2fcac49b386319bd8501.pdf','1769666690_2b8569616bc8a89fe986.pdf',NULL,'Lolos_Final',NULL,NULL,NULL,NULL,'',0,'2026-07-21 14:10:53',0,1,NULL,NULL,NULL,NULL,NULL,NULL,'2026-02-02 13:15:00',NULL,NULL,NULL,NULL,NULL,'2026-01-29 13:04:50','2026-07-21 17:21:58'),(10,'260714000010','Agif Zaki Fadhilah','agifzaki4@gmail.com','081268052086',NULL,'Universitas Negeri Semarang','Ekonomi Pembangunan','Belum Ditentukan',6,'Wajib','2026-02-09','2026-05-29','1769685745_5c6ae4ddf26e521f176d.pdf','1769685745_d54f48